    async def list_cluster_suggested_indexes(
        self,
        group_id: str,
        cluster_name: str,
        *,
        process_ids: typing.Optional[typing.Union[str, typing.Sequence[str]]] = None,
        namespaces: typing.Optional[typing.Union[str, typing.Sequence[str]]] = None,
        since: typing.Optional[int] = None,
        until: typing.Optional[int] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> PerformanceAdvisorResponse:
        """
        Returns the indexes that the Performance Advisor suggests. The Performance Advisor monitors queries that MongoDB considers slow and suggests new indexes to improve query performance. To use this resource, the requesting Service Account or API Key must have the Project Read Only role.

        Parameters
        ----------
        group_id : str
            Unique 24-hexadecimal digit string that identifies your project. Use the [/groups](#tag/Projects/operation/listProjects) endpoint to retrieve all projects to which the authenticated user has access.

            **NOTE**: Groups and projects are synonymous terms. Your group id is the same as your project id. For existing groups, your group/project id remains the same. The resource and corresponding endpoints use the term groups.

        cluster_name : str
            Human-readable label that identifies the cluster.

        process_ids : typing.Optional[typing.Union[str, typing.Sequence[str]]]
            Process IDs from which to retrieve suggested indexes. A `processId` is a combination of host and port that serves the MongoDB process. The host must be the hostname, FQDN, IPv4 address, or IPv6 address of the host that runs the MongoDB process (`mongod` or `mongos`). The port must be the IANA port on which the MongoDB process listens for requests. To include multiple `processIds`, pass the parameter multiple times delimited with an ampersand (`&`) between each `processId`.

        namespaces : typing.Optional[typing.Union[str, typing.Sequence[str]]]
            Namespaces from which to retrieve suggested indexes. A namespace consists of one database and one collection resource written as `.`: `<database>.<collection>`. To include multiple namespaces, pass the parameter multiple times delimited with an ampersand (`&`) between each namespace. Omit this parameter to return results for all namespaces.

        since : typing.Optional[int]
            Date and time from which the query retrieves the suggested indexes. This parameter expresses its value in the number of milliseconds that have elapsed since the [UNIX epoch](https://en.wikipedia.org/wiki/Unix_time).

            - If you don't specify the **until** parameter, the endpoint returns data covering from the **since** value and the current time.
            - If you specify neither the **since** nor the **until** parameters, the endpoint returns data from the previous 24 hours.

        until : typing.Optional[int]
            Date and time up until which the query retrieves the suggested indexes. This parameter expresses its value in the number of milliseconds that have elapsed since the [UNIX epoch](https://en.wikipedia.org/wiki/Unix_time).

            - If you specify the **until** parameter, you must specify the **since** parameter.
            - If you specify neither the **since** nor the **until** parameters, the endpoint returns data from the previous 24 hours.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        PerformanceAdvisorResponse
            OK

        Examples
        --------
        import asyncio

        from atlas_sdk import AsyncAtlasClient

        client = AsyncAtlasClient(
            token="YOUR_TOKEN",
        )


        async def main() -> None:
            await client.performance_advisor.list_cluster_suggested_indexes(
                group_id="32b6e34b3d91647abb20e7b8",
                cluster_name="clusterName",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.list_cluster_suggested_indexes(
            group_id,
            cluster_name,
            process_ids=process_ids,
            namespaces=namespaces,
            since=since,
            until=until,
            request_options=request_options,
        )
        return _response.data

